//
//  FlagAssetTests.swift
//  TravelLogTests
//
//  The bundled vector flags (Flags.xcassets, generated by
//  scripts/build-flag-assets.py): every catalog country ships one, the
//  generated code set matches the catalog, unknown codes fall back to the
//  placeholder, and widget/snippet emoji strings decode back to their codes.
//

import Testing
import UIKit
@testable import TravelLog

struct FlagAssetTests {

    @Test("every catalog country has a bundled 4:3 flag image")
    func everyCatalogCodeHasAnAsset() throws {
        for code in CountryCatalog.isoCountryCodes.sorted() {
            let name = try #require(FlagView.assetName(for: code), "no flag for \(code)")
            let image = try #require(UIImage(named: name), "\(name) missing from the bundle")
            #expect(abs(image.size.width / image.size.height - 4.0 / 3.0) < 0.01, "\(name) is not 4:3")
        }
    }

    @Test("the generated code set is exactly the catalog")
    func shippedSetMatchesCatalog() {
        #expect(FlagAssetCodes.shipped == Set(CountryCatalog.isoCountryCodes.map { $0.lowercased() }))
    }

    @Test("asset names are case-insensitive", arguments: ["GR", "gr", "Gr"])
    func assetNameIgnoresCase(code: String) {
        #expect(FlagView.assetName(for: code) == "flag-gr")
    }

    @Test("unknown or malformed codes get the placeholder, never another flag",
          arguments: [nil, "", "G", "GRC", "XP", "EU", "UN", "12", "ß", "🇬🇷"] as [String?])
    func unknownCodesHaveNoAsset(code: String?) {
        #expect(FlagView.assetName(for: code) == nil)
    }

    @Test("flag emoji decode back to their codes for every catalog country")
    func emojiRoundTrip() throws {
        for code in CountryCatalog.isoCountryCodes.sorted() {
            let emoji = try #require(flagEmoji(for: code))
            #expect(FlagView.isoCodes(fromFlagEmoji: emoji) == [code])
        }
    }

    @Test("joined and spaced emoji strings keep visit order")
    func emojiStringsKeepOrder() {
        #expect(FlagView.isoCodes(fromFlagEmoji: "🇬🇧🇫🇷🇩🇪") == ["GB", "FR", "DE"])
        #expect(FlagView.isoCodes(fromFlagEmoji: "🇵🇹 🇪🇸") == ["PT", "ES"])
        #expect(FlagView.isoCodes(fromFlagEmoji: "") == [])
        // A lone regional indicator cut by another character pairs with nothing.
        #expect(FlagView.isoCodes(fromFlagEmoji: "🇬x🇬🇷") == ["GR"])
        #expect(FlagView.isoCodes(fromFlagEmoji: "🇬") == [])
    }
}
